require 'page-guard.php';require '../config/db_conn.php';require 'components.php';$conn->query("CREATE TABLE IF NOT EXISTS sections (SECTION_ID INT AUTO_INCREMENT PRIMARY KEY, SECTION VARCHAR(80) NOT NULL UNIQUE)");$sectionResult=$conn->query("SELECT SECTION FROM sections UNION SELECT DISTINCT SECTION FROM students WHERE SECTION IS NOT NULL AND SECTION<>'' UNION SELECT DISTINCT SECTION FROM teachers WHERE SECTION IS NOT NULL AND SECTION<>'' ORDER BY SECTION");$sectionOptions=[['value'=>'all','label'=>'All sections']];while($row=$sectionResult->fetch_assoc())$sectionOptions[]=['value'=>$row['SECTION'],'label'=>$row['SECTION']];$studentResult=$conn->query('SELECT STUDENT_ID,STUDENT_NAME FROM students ORDER BY STUDENT_NAME');$studentOptions=[];while($row=$studentResult->fetch_assoc())$studentOptions[]=['value'=>$row['STUDENT_ID'],'label'=>$row['STUDENT_NAME'].' · '.$row['STUDENT_ID']];adminHead('Attendance log');adminSidebar('attendance','Attendance log','Filter and export attendance records.'); ?>
<div class="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div class="flex flex-col justify-between gap-4 border-b border-slate-100 pb-5 sm:flex-row sm:items-end"><div><h2 class="text-2xl font-black text-slate-900">Attendance log</h2><p class="mt-1 text-slate-500">Records refresh automatically every few seconds.</p></div><a id="export-link" href="export-attendance.php?date=<?= date('Y-m-d') ?>&section=all" class="rounded-xl border border-slate-300 px-4 py-3 text-center text-sm font-bold text-slate-700 hover:bg-slate-50">Export spreadsheet</a></div><div class="mt-5 grid gap-4 lg:grid-cols-3"><label class="relative text-sm font-bold text-slate-700">Section<div class="relative mt-2"><input id="sectionFilter" class="w-full rounded-xl border border-slate-300 bg-white px-4 py-3" value="All sections" placeholder="Search sections" autocomplete="off"><div id="sectionOptions" class="absolute inset-x-0 z-20 mt-2 hidden max-h-56 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl"></div></div></label><label class="relative text-sm font-bold text-slate-700">Student name<div class="relative mt-2"><input id="studentFilter" class="w-full rounded-xl border border-slate-300 bg-white px-4 py-3" placeholder="Search students" autocomplete="off"><div id="studentOptions" class="absolute inset-x-0 z-20 mt-2 hidden max-h-56 overflow-y-auto rounded-xl border border-slate-200 bg-white p-1 shadow-xl"></div></div></label><label class="text-sm font-bold text-slate-700">Date<input id="dateFilter" type="date" value="<?= date('Y-m-d') ?>" class="mt-2 w-full rounded-xl border border-slate-300 px-4 py-3"></label></div><div class="mt-6 overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-4 py-3">Student ID</th><th class="px-4 py-3">Name</th><th class="px-4 py-3">Section</th><th class="px-4 py-3">Date</th><th class="px-4 py-3">Time in</th><th class="px-4 py-3">Status</th></tr></thead><tbody id="attendance-rows" class="divide-y divide-slate-100"></tbody></table></div></div><script>const sectionInput=document.getElementById('sectionFilter'),studentInput=document.getElementById('studentFilter'),date=document.getElementById('dateFilter'),rows=document.getElementById('attendance-rows'),exportLink=document.getElementById('export-link'),sectionItems=<?= json_encode($sectionOptions) ?>,studentItems=<?= json_encode($studentOptions) ?>;let sectionValue='all',studentValue='';function drawMenu(input,menu,items,onSelect){const query=(input.value==='All sections'?'':input.value).toLowerCase();menu.innerHTML='';items.filter(item=>item.label.toLowerCase().includes(query)).forEach(item=>{const button=document.createElement('button');button.type='button';button.className='block w-full rounded-lg px-3 py-2 text-left text-sm hover:bg-slate-100';button.textContent=item.label;button.onclick=()=>{input.value=item.label;onSelect(item.value);menu.classList.add('hidden')};menu.appendChild(button)});menu.classList.toggle('hidden',!menu.children.length)}function bindSearch(input,menu,items,onSelect,onTyping){input.onfocus=()=>drawMenu(input,menu,items,onSelect);input.oninput=()=>{onTyping();drawMenu(input,menu,items,onSelect)};input.onkeydown=event=>{if(event.key==='Escape')menu.classList.add('hidden')}}bindSearch(sectionInput,document.getElementById('sectionOptions'),sectionItems,value=>{sectionValue=value;update()},()=>{sectionValue=sectionInput.value==='All sections'?'all':sectionInput.value});bindSearch(studentInput,document.getElementById('studentOptions'),studentItems,value=>{studentValue=value;update()},()=>{studentValue=studentInput.value});document.addEventListener('click',event=>{if(!event.target.closest('.relative')){document.getElementById('sectionOptions').classList.add('hidden');document.getElementById('studentOptions').classList.add('hidden')}});function params(){return new URLSearchParams({section:sectionValue||'all',student:studentValue,date:date.value})}function update(){const p=params();rows.innerHTML='<tr><td colspan="6" class="px-4 py-8 text-center text-slate-500">Loading records…</td></tr>';fetch('get-latest-attendance.php?'+p).then(r=>r.text()).then(x=>rows.innerHTML=x).catch(()=>rows.innerHTML='<tr><td colspan="6" class="px-4 py-8 text-center text-rose-600">Could not load records.</td></tr>');exportLink.href='export-attendance.php?'+p}date.onchange=update;update();setInterval(update,10000)</script><?php adminFoot(); ?>